import { AxisScale } from '@visx/axis';
import { getTicks } from '@visx/scale';

import {
  ConvertibleUnit,
  FormatOptions,
  Unit,
  format,
} from '@dynatrace-sdk/units';

import { defaultUnitFormatter } from './defaultUnitFormatter.js';
import { getFormatterPrecision, getTickValues } from './format-value.js';
import { getYAxisTickFormatter } from '../components/axes/functions/tick-formatters.js';
import { ChartUnit } from '../types/chart-unit.js';
import {
  Formatter,
  isFormatterOptions,
  FormatterWithPrecision,
} from '../types/formatter.js';

export interface TickAxis {
  ticks: string[];
  formattedTicks: string[];
}

export function getFormatterByTicks(
  numTicks: number,
  scale: AxisScale | undefined,
  unit: ChartUnit,
  formatter: Formatter | FormatOptions<Unit, ConvertibleUnit> | undefined,
) {
  if (!scale) {
    return defaultUnitFormatter(unit);
  }

  const ticks = getTicks(scale, numTicks);
  let axisFormatter: FormatterWithPrecision;

  const isDefaultFormatter = !formatter;
  const isCustomFormatter = !isFormatterOptions(formatter);
  const isCustomFormatterOrHasPrecisionDefined =
    isCustomFormatter ||
    formatter.maximumFractionDigits ||
    formatter.minimumFractionDigits;

  if (isDefaultFormatter) {
    const precisionFormatter = (
      value: number,
      unit: ChartUnit,
      precision: number,
    ) => defaultUnitFormatter(unit, precision)(value);

    const precision = getFormatterPrecision(ticks, precisionFormatter, unit);

    axisFormatter = defaultUnitFormatter(unit, precision);
  } else if (isCustomFormatterOrHasPrecisionDefined) {
    axisFormatter = isCustomFormatter
      ? formatter
      : (value: number) =>
          format(value, formatter as FormatOptions<Unit, ConvertibleUnit>);
  } else {
    const precisionFormatter = (
      value: number,
      unit: ChartUnit,
      precision: number,
    ) =>
      format(value, {
        maximumFractionDigits: precision,
        minimumFractionDigits: precision,
        ...(formatter as FormatOptions<Unit, ConvertibleUnit>),
      });
    const precision = getFormatterPrecision(ticks, precisionFormatter, unit);

    axisFormatter = (value: number) =>
      format(value, {
        maximumFractionDigits: precision,
        ...(formatter as FormatOptions<Unit, ConvertibleUnit>),
      });
  }

  return axisFormatter;
}

export function getFormattedTicks(
  numTicks: number,
  scale: AxisScale | undefined,
  unit: ChartUnit,
  formatter: Formatter | undefined,
) {
  if (!scale) {
    return { ticks: [], formattedTicks: [] };
  }

  const ticks = getTicks(scale, numTicks);

  const formattedTicks = getTickValues(
    ticks,
    getYAxisTickFormatter(scale, unit, formatter, numTicks),
  );

  return { ticks, formattedTicks };
}
